  const isNd=re.test(String.fromCodePoint(cp));
  if(isNd){ if(start<0) start=cp; } else if(start>=0){ runs.push([start,cp-1]); start=-1; }
}
if(start>=0) runs.push([start,0x10FFFF]);
const bad=runs.filter(([a,b])=>(b-a+1)%10!==0);
console.log("runs:",runs.length,"non-multiple-of-10:",JSON.stringify(bad));
console.log("total digits:",runs.reduce((s,[a,b])=>s+b-a+1,0));
