/**
 * Unicode decimal-digit (General_Category=Nd) data.
 *
 * Python's `int()` accepts any Unicode decimal digit, not just ASCII 0-9:
 *   int('٥')  -> 5     (ARABIC-INDIC DIGIT FIVE)
 *   int('1٥') -> 15    (scripts may even be mixed)
 * while non-Nd digit-like characters are rejected:
 *   int('²')  -> ValueError  (SUPERSCRIPT TWO, category No)
 *   int('Ⅰ')  -> ValueError  (ROMAN NUMERAL ONE, category Nl)
 *
 * Every Nd character belongs to a run whose length is a multiple of ten, and
 * inside a run the digits appear in ascending order 0..9. So the numeric value
 * of a code point is `(cp - runStart) % 10`. Runs are stored as
 * `[firstCodePoint, length]` pairs sorted by `firstCodePoint`.
 */

const ND_RUNS = [
  [48, 10], [1632, 10], [1776, 10], [1984, 10], [2406, 10], [2534, 10],
  [2662, 10], [2790, 10], [2918, 10], [3046, 10], [3174, 10], [3302, 10],
  [3430, 10], [3558, 10], [3664, 10], [3792, 10], [3872, 10], [4160, 10],
  [4240, 10], [6112, 10], [6160, 10], [6470, 10], [6608, 10], [6784, 10],
  [6800, 10], [6992, 10], [7088, 10], [7232, 10], [7248, 10], [42528, 10],
  [43216, 10], [43264, 10], [43472, 10], [43504, 10], [43600, 10], [44016, 10],
  [65296, 10], [66720, 10], [68912, 10], [69734, 10], [69872, 10], [69942, 10],
  [70096, 10], [70384, 10], [70736, 10], [70864, 10], [71248, 10], [71360, 10],
  [71472, 10], [71904, 10], [72016, 10], [72784, 10], [73040, 10], [73120, 10],
  [73552, 10], [92768, 10], [92864, 10], [93008, 10], [120782, 50],
  [123200, 10], [123632, 10], [124144, 10], [125264, 10], [130032, 10],
];

// Fallback for code points that a newer Unicode revision may have added after
// the table above was generated. Isolated new runs are handled correctly by
// walking back to the run start; the one multi-set run that exists today
// (mathematical digits at U+1D7CE) is already in the table.
const ND_PATTERN = /^\p{Nd}$/u;

function isNdChar(cp) {
  if (cp < 0 || cp > 0x10ffff) return false;
  if (cp >= 0xd800 && cp <= 0xdfff) return false;
  return ND_PATTERN.test(String.fromCodePoint(cp));
}

/** Index of the run containing `cp`, or -1. */
function findRunIndex(cp) {
  let lo = 0;
  let hi = ND_RUNS.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const [start, length] = ND_RUNS[mid];
    if (cp < start) hi = mid - 1;
    else if (cp >= start + length) lo = mid + 1;
    else return mid;
  }
  return -1;
}

/** True when `cp` has General_Category=Nd, i.e. Python's `str.isdigit`-style decimal digit. */
export function isDecimalDigit(cp) {
  if (findRunIndex(cp) !== -1) return true;
  return isNdChar(cp);
}

/**
 * Numeric value 0-9 of a decimal digit code point, or -1 when `cp` is not one.
 */
export function decimalDigitValue(cp) {
  const index = findRunIndex(cp);
  if (index !== -1) {
    return (cp - ND_RUNS[index][0]) % 10;
  }
  if (!isNdChar(cp)) return -1;
  // Unknown run: walk back at most nine places to locate its first digit.
  let start = cp;
  for (let step = 1; step <= 9; step += 1) {
    if (!isNdChar(cp - step)) break;
    start = cp - step;
  }
  return cp - start;
}

