/**
 * Python's `str.isprintable()`, which decides what `repr()` escapes.
 *
 * A character is non-printable when its General_Category is one of Cc, Cf, Cs,
 * Co, Cn, Zl, Zp or Zs -- with SPACE (U+0020) carved out as printable. That is
 * why the reference escapes U+00A0 (Zs) as `\xa0` and U+200B (Cf) as `​`,
 * yet prints `é` and combining marks literally.
 */
const NON_PRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;

/** True when `cp` is printable in Python's sense. */
export function isPrintable(cp) {
  if (cp === 0x20) return true;
  if (cp >= 0xd800 && cp <= 0xdfff) return false;
  return !NON_PRINTABLE.test(String.fromCodePoint(cp));
}

