export class PythonError extends Error {
  constructor(message) {
    super(message);
    this.name = 'PythonError';
  }
}

/** Raised by `pyInt` for strings that Python's `int()` rejects. */
export class ValueError extends PythonError {
  constructor(message) {
    super(message);
    this.name = 'ValueError';
  }
}

/** Raised by `struct.pack` when a value does not fit the format character. */
export class StructError extends PythonError {
  constructor(message) {
    super(message);
    this.name = 'StructError';
    this.pythonClass = 'struct.error';
