import { isPythonWhitespace } from '../unicode/whitespace.mjs';
import { isDecimalDigit, decimalDigitValue } from '../unicode/nd-digits.mjs';
import { ValueError } from './errors.mjs';

/**
 * `int(text)` with base 10, matching CPython's accept/reject surface.
 *
 * Grammar, after stripping Python whitespace from both ends:
 *     [+-] digit (_? digit)*
 * where `digit` is any Unicode decimal digit. Underscores must sit between two
 * digits, so `_10`, `10_` and `1__0` are all errors while `1_0_0` is 100.
 *
 * Returns a BigInt so that oversized inputs survive intact -- the reference
 * reports the full value in its range error ("given value 99999999999999999999")
 * and Python integers never overflow.
 */
export function pyInt(text) {
  const codePoints = Array.from(text, (ch) => ch.codePointAt(0));

  let start = 0;
  let end = codePoints.length;
  while (start < end && isPythonWhitespace(codePoints[start])) start += 1;
  while (end > start && isPythonWhitespace(codePoints[end - 1])) end -= 1;

  let negative = false;
  if (start < end && (codePoints[start] === 0x2b || codePoints[start] === 0x2d)) {
    negative = codePoints[start] === 0x2d;
    start += 1;
  }

  let digits = '';
  let expectDigit = true;
  for (let i = start; i < end; i += 1) {
    const cp = codePoints[i];
    if (cp === 0x5f) {
      // Underscore: legal only directly after a digit.
      if (expectDigit) throw invalidInt(text);
      expectDigit = true;
      continue;
    }
    if (!isDecimalDigit(cp)) throw invalidInt(text);
    digits += String(decimalDigitValue(cp));
    expectDigit = false;
  }
  // Empty digit run, or a trailing underscore.
  if (expectDigit) throw invalidInt(text);

  const value = BigInt(digits);
  return negative ? -value : value;
}

function invalidInt(text) {
  return new ValueError(`invalid literal for int() with base 10: ${text}`);
}

