/**
 * Byte-level helpers. Bytes are plain arrays of numbers 0-255 throughout, so no
 * binary view types are needed anywhere in this port.
 */

/** Code points of `text`, so that astral characters count once (as in Python). */
export function codePoints(text) {
  return Array.from(text, (ch) => ch.codePointAt(0));
}

/** `len(text)` -- Python counts code points, unlike JS `String.length`. */
export function pyLen(text) {
  return codePoints(text).length;
}

/** `text.encode()` -- UTF-8, returned as an array of byte values. */
export function encodeUtf8(text) {
  const bytes = [];
  for (const cp of codePoints(text)) {
    if (cp < 0x80) {
      bytes.push(cp);
    } else if (cp < 0x800) {
      bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      bytes.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      bytes.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f),
      );
    }
  }
  return bytes;
}

