const QUOTE_SINGLE = 0x27;
const QUOTE_DOUBLE = 0x22;
const BACKSLASH = 0x5c;

/** Short escapes shared by `bytes.__repr__` and `str.__repr__`. */
const SHORT_ESCAPES = new Map([
  [0x09, '\\t'],
  [0x0a, '\\n'],
  [0x0d, '\\r'],
]);

/**
 * Python quote choice: prefer single quotes; switch to double quotes only when
 * the value contains a single quote and no double quote. When it contains both,
 * stay on single quotes and backslash-escape them.
 */
function chooseQuote(units) {
  const hasSingle = units.includes(QUOTE_SINGLE);
  const hasDouble = units.includes(QUOTE_DOUBLE);
  return hasSingle && !hasDouble ? QUOTE_DOUBLE : QUOTE_SINGLE;
}

function hexEscape(value) {
  if (value < 0x100) return `\\x${value.toString(16).padStart(2, '0')}`;
  if (value < 0x10000) return `\\u${value.toString(16).padStart(4, '0')}`;
  return `\\U${value.toString(16).padStart(8, '0')}`;
