/**
 * Standard-stream access.
 *
 * Writes go through `process.std*.write` and the exit status is published via
 * `process.exitCode` rather than `process.exit()`, so Node always flushes both
 * streams before the process ends -- `process.exit()` can truncate output when
 * stdout is a pipe.
 */

/** `print(text)` -- one line, LF terminated. */
export function printLine(text) {
  process.stdout.write(`${text}\n`);
}

/** `sys.stdout.write(text)` -- verbatim, no terminator added. */
export function writeStdout(text) {
  process.stdout.write(text);
}

/** `sys.stderr.write(text)` -- verbatim, no terminator added. */
export function writeStderr(text) {
  process.stderr.write(text);
}

/**
 * Terminal width as `shutil.get_terminal_size()` reports it: the COLUMNS
 * environment variable wins, then the real terminal, then the 80-column
 * fallback used whenever stdout is redirected.
 */
export function terminalColumns() {
  const fromEnv = process.env.COLUMNS;
  if (fromEnv !== undefined && fromEnv !== '') {
    const parsed = Number.parseInt(fromEnv, 10);
    if (Number.isInteger(parsed) && parsed > 0) return parsed;
  }
  if (process.stdout.isTTY && process.stdout.columns > 0) {
    return process.stdout.columns;
  }
  return 80;
}

