/** argparse control-flow signals. */

/**
 * Raised instead of calling `sys.exit()`, so the entry point can flush both
 * streams and set `process.exitCode` itself.
 */
export class ArgumentParserExit extends Error {
  constructor(status, output, stream) {
    super(`argparse exit ${status}`);
    this.name = 'ArgumentParserExit';
    this.status = status;
    /** Text to emit before exiting. */
    this.output = output;
    /** Either 'stdout' (for --help) or 'stderr' (for errors). */
    this.stream = stream;
  }
}

/**
 * A per-argument failure. `parser.error()` renders it as
 * `argument --a: invalid int value: 'abc'`.
 */
export class ArgumentError extends Error {
  constructor(action, message) {
    super(message);
    this.name = 'ArgumentError';
    this.action = action;
    this.rawMessage = message;
  }
}

