/**
 * A port of argparse's `HelpFormatter`, limited to what this program's parser
 * needs (optionals only, `nargs` of 0 or 1, no groups beyond the default ones).
 *
 * The usage wrapper is the subtle part. argparse does not keep `--a A` together
 * when it wraps: it splits the usage string with
 *
 *     r'\(.*?\)+(?=\s|$)|\[.*?\]+(?=\s|$)|\S+'
 *
 * so a bracketed group like `[-h]` stays atomic while a *required* option and
 * its metavar become two independent parts. That is why the reference can break
 * a line between `--e` and `E`.
 */

const PART_PATTERN = /\(.*?\)+(?=\s|$)|\[.*?\]+(?=\s|$)|\S+/g;
const MAX_HELP_POSITION = 24;
const SECTION_INDENT = 2;

export class HelpFormatter {
  constructor({ prog, width }) {
    this.prog = prog;
    this.width = width;
  }

  /** Longest `indent + invocation`, which decides where help text starts. */
  actionMaxLength(actions) {
    let max = 0;
    for (const action of actions) {
      const length = formatActionInvocation(action).length + SECTION_INDENT;
      if (length > max) max = length;
    }
    return max;
  }

  /** The raw usage block, terminated by a blank line as argparse produces it. */
  formatUsage(actions) {
    const prefix = 'usage: ';
    const optionalUsage = formatActionsUsage(actions);
    const textWidth = this.width;

    let usage = [this.prog, optionalUsage].filter((piece) => piece).join(' ');

    if (prefix.length + usage.length > textWidth) {
      const optParts = optionalUsage.match(PART_PATTERN) ?? [];
      let lines;
      if (prefix.length + this.prog.length <= 0.75 * textWidth) {
        const indent = ' '.repeat(prefix.length + this.prog.length + 1);
        lines = optParts.length
          ? getLines([this.prog, ...optParts], indent, textWidth, prefix)
          : [this.prog];
      } else {
        const indent = ' '.repeat(prefix.length);
        lines = [this.prog, ...getLines(optParts, indent, textWidth)];
      }
      usage = lines.join('\n');
    }

    return `${prefix}${usage}\n\n`;
  }

  /** The `--help` output. */
  formatHelp(actions) {
    const helpPosition = Math.min(this.actionMaxLength(actions) + 2, MAX_HELP_POSITION);
    const items = actions
      .map((action) => this.formatAction(action, helpPosition))
      .join('');
