import { ArgumentParserExit, ArgumentError } from './errors.mjs';
import { HelpFormatter, finalize } from './help-formatter.mjs';
import { terminalColumns } from '../python/stdio.mjs';

/** argparse's `_negative_number_matcher`. */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

/**
 * `argparse.ArgumentParser`, covering the behaviour this program exercises:
 * long options only, `nargs` of 0 or 1, `required=True`, and a `type` callable
 * whose failures become "invalid ... value" errors.
 *
 * Error precedence -- established against the reference -- is:
 *   1. per-argument failures raised while consuming argv (bad value, missing
 *      value) in left-to-right order;
 *   2. missing required arguments, listed in declaration order;
 *   3. unrecognized arguments.
 * `--help` is honoured only when argv is consumed far enough to reach it, so
 * `--a abc -h` still reports the bad int.
 */
export class ArgumentParser {
  constructor({ prog } = {}) {
    this.prog = prog ?? 'prog';
    this.actions = [];
    this.optionStringActions = new Map();
    this.addArgument({
      optionStrings: ['-h', '--help'],
      dest: 'help',
      nargs: 0,
      action: 'help',
      help: 'show this help message and exit',
    });
  }

  addArgument({
    optionStrings,
    dest,
    nargs = 1,
    type,
    required = false,
    action = 'store',
    metavar,
    help = null,
  }) {
    const resolvedDest = dest ?? optionStrings[optionStrings.length - 1].replace(/^-+/, '');
    const entry = {
      optionStrings,
      dest: resolvedDest,
      nargs,
      type,
      required,
      action,
      metavar: metavar ?? resolvedDest.toUpperCase(),
      help,
    };
    this.actions.push(entry);
    for (const optionString of optionStrings) {
      this.optionStringActions.set(optionString, entry);
    }
    return entry;
  }

  get formatter() {
    return new HelpFormatter({ prog: this.prog, width: terminalColumns() - 2 });
  }

  /** `usage: ...` block as it appears above an error, with one trailing newline. */
  formatUsage() {
    return finalize(this.formatter.formatUsage(this.actions));
  }

  formatHelp() {
    return this.formatter.formatHelp(this.actions);
  }

  /** Print usage plus `prog: error: message` to stderr and exit 2. */
  error(message) {
    throw new ArgumentParserExit(
      2,
      `${this.formatUsage()}${this.prog}: error: ${message}\n`,
      'stderr',
    );
  }

  /**
   * Classify one argv token the way `_parse_optional` does.
   * Returns null when the token is a value, or
   * `{ action, optionString, explicitArg }` when it looks like an option --
   * `action` is null for an option-like token no definition matches.
   */
  parseOptional(token) {
    if (token === '') return null;
    if (!token.startsWith('-')) return null;
    if (this.optionStringActions.has(token)) {
      return { action: this.optionStringActions.get(token), optionString: token, explicitArg: null };
    }
    if (token.length === 1) return null; // a bare '-' is a value
    const equals = token.indexOf('=');
    if (equals !== -1) {
      const optionString = token.slice(0, equals);
      if (this.optionStringActions.has(optionString)) {
        return {
          action: this.optionStringActions.get(optionString),
          optionString,
          explicitArg: token.slice(equals + 1),
        };
      }
    }
    const matches = [...this.optionStringActions.keys()].filter((known) => known.startsWith(token));
    if (matches.length > 1) {
      this.error(`ambiguous option: ${token} could match ${matches.join(', ')}`);
    }
    if (matches.length === 1) {
      return {
        action: this.optionStringActions.get(matches[0]),
        optionString: matches[0],
        explicitArg: null,
      };
    }
    // No option string looks like a negative number here, so numeric tokens
    // such as '-5' or '-.5' are values while '-x' and '-5x' are not.
    if (NEGATIVE_NUMBER.test(token)) return null;
    if (token.includes(' ')) return null;
    return { action: null, optionString: token, explicitArg: null };
  }

  parseKnownArgs(argv) {
    const namespace = Object.create(null);
    for (const action of this.actions) {
      if (action.action === 'store') namespace[action.dest] = null;
    }

    const extras = [];
    const seen = new Set();
    let afterSeparator = false;

    for (let i = 0; i < argv.length; i += 1) {
      const token = argv[i];

      if (afterSeparator) {
        extras.push(token);
        continue;
      }
      if (token === '--') {
        // With no positional actions to consume them, the separator and
        // everything after it survive as unrecognized arguments.
        afterSeparator = true;
        extras.push(token);
        continue;
      }

      const optional = this.parseOptional(token);
      if (optional === null || optional.action === null) {
        extras.push(token);
        continue;
      }

      const { action, optionString, explicitArg } = optional;

      if (action.action === 'help') {
        throw new ArgumentParserExit(0, this.formatHelp(), 'stdout');
      }

      let raw;
      if (explicitArg !== null) {
        raw = explicitArg;
      } else {
        const next = i + 1 < argv.length ? argv[i + 1] : undefined;
        // A following token counts as this option's value only if it is not
        // itself option-like -- that is what makes `--d --e` fail.
        const nextIsValue = next !== undefined
          && next !== '--'
          && this.parseOptional(next) === null;
        if (!nextIsValue) {
          this.error(`argument ${optionString}: expected one argument`);
        }
        raw = next;
        i += 1;
      }

      seen.add(action);
      try {
        namespace[action.dest] = action.type ? action.type(raw) : raw;
      } catch (cause) {
        if (cause instanceof ArgumentError) throw cause;
        this.error(`argument ${optionString}: ${cause.message}`);
      }
    }

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => action.optionStrings.join('/'));
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return { namespace, extras };
  }

  parseArgs(argv) {
    const { namespace, extras } = this.parseKnownArgs(argv);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }
}

