/**
 * Renders the CPython traceback that the frozen reference prints to stderr when
 * a `construct` build fails, including the PyInstaller epilogue.
 *
 * Two shapes occur. A `FormatFieldError` is raised while handling a
 * `struct.error`, so its traceback opens with the inner exception and the
 * "During handling of the above exception" chain. A `StreamError` is raised
 * directly and has no such preamble.
 */

const SCRIPT_NAME = 'test19.py';
const CONSTRUCT_FILE = 'construct/core.py';
const MODULE_FRAME = { line: 38, source: 'main()' };

function coreFrame({ line, name }) {
  return `  File "${CONSTRUCT_FILE}", line ${line}, in ${name}`;
