import * as construct from '../construct/index.mjs';
import { ConstructError } from '../construct/errors.mjs';
import { ArgumentParser } from '../argparse/parser.mjs';
import { intType, strType } from '../argparse/types.mjs';
import { pyBytesRepr } from '../python/repr.mjs';
import { pyLen, encodeUtf8 } from '../python/bytes.mjs';
import { printLine } from '../python/stdio.mjs';
import { BUILD_FRAMES } from './build-frames.mjs';

/** Declaration order drives both the usage line and the missing-argument list. */
const ARGUMENTS = [
  { name: 'a', type: intType },
  { name: 'b', type: intType },
  { name: 'c', type: intType },
  { name: 'd', type: strType },
  { name: 'e', type: intType },
  { name: 'f', type: intType },
  { name: 'g', type: intType },
  { name: 'h', type: strType },
  { name: 'i', type: intType },
];

export function buildParser(prog) {
  const parser = new ArgumentParser({ prog });
  for (const { name, type } of ARGUMENTS) {
    parser.addArgument({
      optionStrings: [`--${name}`],
      dest: name,
      type,
      required: true,
    });
  }
  return parser;
}

/**
 * Run one build statement, tagging any construct failure with the source frame
 * so the traceback can name the exact line that raised.
 */
function step(key, thunk) {
  try {
    return thunk();
  } catch (error) {
    if (error instanceof ConstructError) {
      error.userFrame = BUILD_FRAMES[key];
    }
    throw error;
  }
}

/** Python's `%`, which always yields a non-negative result for a positive divisor. */
function pyMod(value, divisor) {
  return ((value % divisor) + divisor) % divisor;
}

/**
 * The body of `main()`.
 *
 * All nine values are built before anything is printed, exactly as in the
 * source -- so a failure on any field leaves stdout completely empty.
 */
export function main(argv, prog) {
  const args = buildParser(prog).parseArgs(argv);

  const result1 = step('result1', () => construct.Int8ul.build(args.a));
  const result2 = step('result2', () => construct.Int16ul.build(args.b));
  const result3 = step('result3', () => construct.Int8ul.build(args.c));
  const result4 = step('result4', () => construct.Bytes(pyLen(args.d)).build(encodeUtf8(args.d)));
  const result5 = step('result5', () => construct.Int8ul.build(args.f));
  const result6 = step('result6', () => construct.Int8ul.build(args.g));
  const result7 = step('result7', () => construct.Int8ul.build(args.i));
  const result8 = step('result8', () => construct.Bytes(pyLen(args.h)).build(encodeUtf8(args.h)));
  const result9 = step(
    'result9',
    () => construct.Int8ul.build(pyMod(args.a + args.b + args.c, 256n)),
  );

  for (const result of [
    result1, result2, result3, result4, result5, result6, result7, result8, result9,
  ]) {
    printLine(pyBytesRepr(result));
  }
}

