#!/usr/bin/env node
/**
 * Node.js port of `test19.py`.
 *
 *   node test19.mjs --a A --b B --c C --d D --e E --f F --g G --h H --i I
 *
 * Behaviour mirrors the Python original end to end: argparse's parsing rules and
 * error precedence, CPython's `int()` accept/reject surface, `construct`'s
 * little-endian builders and their tracebacks, and `repr(bytes)` output. Exit
 * status is 0 on success, 1 for a construct failure, 2 for a usage error.
 */
import { basename } from 'node:path';
import { main } from './lib/app/main.mjs';
import { ArgumentParserExit } from './lib/argparse/errors.mjs';
import { ConstructError } from './lib/construct/errors.mjs';
import { formatTraceback } from './lib/runtime/traceback.mjs';
import { writeStdout, writeStderr } from './lib/python/stdio.mjs';

function run(argv, prog) {
  try {
    main(argv, prog);
    return 0;
  } catch (error) {
    if (error instanceof ArgumentParserExit) {
      // --help goes to stdout and exits 0; usage errors go to stderr and exit 2.
      (error.stream === 'stdout' ? writeStdout : writeStderr)(error.output);
      return error.status;
    }
    if (error instanceof ConstructError) {
      writeStderr(formatTraceback(error));
      return 1;
    }
    throw error;
  }
}

// `process.exitCode` rather than `process.exit()`, so Node flushes stdout even
// when it is a pipe.
process.exitCode = run(process.argv.slice(2), basename(process.argv[1] ?? 'test19.mjs'));

export { run };

