#!/usr/bin/env node
/**
 * Differential harness: runs a case against both the frozen Python reference and
 * the Node port and reports any divergence.
 *
 *   node tools/difftest.mjs --json '[["--a","1",...], ...]'
 *   node tools/difftest.mjs --stdin      # one JSON array of argv per line
 *
 * stdout and the exit status must match byte for byte. stderr is compared after
 * normalising the two intentionally-different parts: the program name argparse
 * prints (test19_executable vs test19.mjs) and the PyInstaller PID.
 */
import { spawnSync } from 'node:child_process';

const REFERENCE = '/workspace/dataset/test19_executable';
const PORT = '/output/test19.mjs';

function normalizeStderr(text) {
  return text
    .replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]')
    .replaceAll('test19_executable', 'PROG')
    .replaceAll('test19.mjs', 'PROG');
}

function runCase(argv, env) {
  const options = { encoding: 'utf8', env: { ...process.env, ...env }, maxBuffer: 1 << 26 };
  const reference = spawnSync(REFERENCE, argv, options);
  const port = spawnSync(process.execPath, [PORT, ...argv], options);
  return { reference, port };
}

export function compare(argv, env = {}) {
  const { reference, port } = runCase(argv, env);
  const problems = [];
  if (reference.stdout !== port.stdout) {
    problems.push(`stdout: ref=${JSON.stringify(reference.stdout)} port=${JSON.stringify(port.stdout)}`);
  }
  if (reference.status !== port.status) {
    problems.push(`exit: ref=${reference.status} port=${port.status}`);
  }
  const refErr = normalizeStderr(reference.stderr);
  const portErr = normalizeStderr(port.stderr);
  if (refErr !== portErr) {
    problems.push(`stderr: ref=${JSON.stringify(refErr)} port=${JSON.stringify(portErr)}`);
  }
  return { argv, env, ok: problems.length === 0, problems };
}

function main() {
  const [mode, payload] = process.argv.slice(2);
  let cases;
  if (mode === '--json') {
    cases = JSON.parse(payload);
  } else {
    const text = await0(process.stdin);
    cases = text.split('\n').filter((line) => line.trim()).map((line) => JSON.parse(line));
  }
  let failures = 0;
  for (const entry of cases) {
    const argv = Array.isArray(entry) ? entry : entry.argv;
    const env = Array.isArray(entry) ? {} : (entry.env ?? {});
    const result = compare(argv, env);
    if (!result.ok) {
      failures += 1;
      console.log(`FAIL ${JSON.stringify(argv)}${Object.keys(env).length ? ` env=${JSON.stringify(env)}` : ''}`);
      for (const problem of result.problems) console.log(`     ${problem}`);
    }
  }
  console.log(`\n${cases.length - failures}/${cases.length} cases match`);
  process.exitCode = failures === 0 ? 0 : 1;
}

function await0(stream) {
  const chunks = [];
  const fs = require('node:fs');
  return fs.readFileSync(0, 'utf8');
}

main();

