#!/usr/bin/env node
/**
 * Differential harness: runs each case against both the frozen Python reference
 * and the Node port and reports every divergence.
 *
 *   node tools/gen-cases.mjs > cases.json
 *   node tools/difftest.mjs cases.json [concurrency]
 *
