 * normalising the two intentionally-different parts: the program name argparse
 * prints (test19_executable vs test19.mjs) and the PyInstaller PID.
 *
 * Cases run concurrently -- the frozen reference takes ~100 ms to start, so a
 * serial sweep of a few hundred cases is needlessly slow.
 */
import { spawn } from 'node:child_process';
import { readFileSync } from 'node:fs';

const REFERENCE = '/workspace/dataset/test19_executable';
const PORT = '/output/test19.mjs';

function normalizeStderr(text) {
  return text
    .replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]')
    .replaceAll('test19_executable', 'PROG')
    .replaceAll('test19.mjs', 'PROG');
}

function run(command, argv, env) {
  return new Promise((resolve) => {
    const child = spawn(command, argv, { env: { ...process.env, ...env } });
    let stdout = '';
    let stderr = '';
    child.stdout.setEncoding('utf8');
    child.stderr.setEncoding('utf8');
    child.stdout.on('data', (chunk) => { stdout += chunk; });
    child.stderr.on('data', (chunk) => { stderr += chunk; });
    child.on('close', (status) => resolve({ stdout, stderr, status }));
  });
}

/** Run one argv against both implementations and list every divergence. */
export async function compare(argv, env = {}) {
  const [reference, port] = await Promise.all([
    run(REFERENCE, argv, env),
    run(process.execPath, [PORT, ...argv], env),
  ]);

  const problems = [];
  if (reference.stdout !== port.stdout) {
    problems.push(
      `stdout: ref=${JSON.stringify(reference.stdout)} port=${JSON.stringify(port.stdout)}`,
    );
  }
  if (reference.status !== port.status) {
    problems.push(`exit: ref=${reference.status} port=${port.status}`);
  }
  const referenceStderr = normalizeStderr(reference.stderr);
  const portStderr = normalizeStderr(port.stderr);
  if (referenceStderr !== portStderr) {
    problems.push(
      `stderr: ref=${JSON.stringify(referenceStderr)} port=${JSON.stringify(portStderr)}`,
    );
  }
  return { argv, env, ok: problems.length === 0, problems };
}

/** Map over `items` with at most `limit` promises in flight. */
async function mapLimit(items, limit, worker) {
  const results = new Array(items.length);
  let next = 0;
  const runners = Array.from({ length: Math.min(limit, items.length) }, async () => {
    while (next < items.length) {
      const index = next;
      next += 1;
      results[index] = await worker(items[index]);
    }
  });
  await Promise.all(runners);
  return results;
}

async function main() {
  const [path, concurrency = '16'] = process.argv.slice(2);
  const cases = JSON.parse(readFileSync(path, 'utf8'));

  const results = await mapLimit(cases, Number(concurrency), (entry) => {
    const argv = Array.isArray(entry) ? entry : entry.argv;
    const env = Array.isArray(entry) ? {} : (entry.env ?? {});
    return compare(argv, env);
  });

  const failures = results.filter((result) => !result.ok);
  for (const failure of failures) {
    const envNote = Object.keys(failure.env).length > 0
      ? ` env=${JSON.stringify(failure.env)}`
      : '';
    console.log(`FAIL ${JSON.stringify(failure.argv)}${envNote}`);
    for (const problem of failure.problems) console.log(`     ${problem}`);
  }
  console.log(`${results.length - failures.length}/${results.length} cases match`);
  process.exitCode = failures.length === 0 ? 0 : 1;
}

